L6 Presentation:
[TLS wraps full HTTP request]
TLS Record {
  Version: TLS 1.3
  Encrypted Payload: [signed URL request]
}

L5 Session:
[Auth embedded in URL not cookie]
CloudFront Session {
  Edge: us-east-1
  State: Active
  Auth: embedded in URL
}

L6 Presentation:
[TLS encrypts cookies too]
TLS Record {
  Version: TLS 1.3
  Encrypted Payload: [cookie-auth request]
}

L5 Session:
[Cookies scope access to path]
Signed Cookie Session {
  Scope: /premium/*
  Expires: 2026-11-19T00:00:00Z
  Cookies: 3 CloudFront cookies
}

L6 Presentation:
[SNI carries raw CloudFront domain]
TLS Record {
  Version: TLS 1.3
  SNI: d111111abcdef8.cloudfront.net
  Encrypted Payload: [GET request]
}

L5 Session:
[Edge session, no custom domain]
CloudFront Session {
  Edge: us-east-1
  Distribution: d111111abcdef8
  State: Active
}

[CNAME resolves to distribution]
CloudFront Session {
  Edge: us-east-1
  CNAME: cdn.example.com
  Distribution: d111111abcdef8
}

L6 Presentation:
[DNS unencrypted, wire format]
No Encryption {
  Encoding: DNS wire format
  Passes: unchanged
}

L5 Session:
[Stateless, one-shot lookup]
Stateless {
  Session: None
  Independent: true
}

L6 Presentation:
[No TLS — S3 website endpoint is HTTP only]
No Encryption {
  S3 website endpoint: HTTP only
  TLS: not supported here
  Passes: unchanged
}

L5 Session:
[S3 has no session concept]
Stateless {
  Session: None
  S3 is object storage
  No session tracking
}

[Cache HIT — S3 not contacted]
CloudFront Session {
  Edge: nearest PoP
  Origin: mybucket.s3.amazonaws.com
  Cache: HIT
}
